#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,m,k;cin>>n>>m>>k;vector<vector<int>> ch(n);vector<int> indeg(n),h(n,1);for(int i=0;i<n;i++){int p;cin>>p;if(p){--p;ch[p].push_back(i);indeg[i]=1;}}queue<int> q;for(int i=0;i<n;i++)if(!indeg[i])q.push(i);vector<int> order;while(!q.empty()){int u=q.front();q.pop();order.push_back(u);for(int v:ch[u]){h[v]=max(h[v],h[u]+1);if(--indeg[v]==0)q.push(v);}}vector<int> rem(n,1);for(int z=n-1;z>=0;z--){int u=order[z];for(int v:ch[u])rem[u]=max(rem[u],rem[v]+1);}vector<int> cur;for(int i=0;i<n;i++)if(!indeg[i]&&h[i]<=m)cur.push_back(i);long long ans=0;for(int sem=1;sem<=m&&!cur.empty();sem++){priority_queue<pair<int,int>> pq;for(int u:cur)pq.push({rem[u],u});vector<int> next;int used=0;while(used<k&&!pq.empty()){int u=pq.top().second;pq.pop();ans++;used++;for(int v:ch[u])next.push_back(v);}cur.swap(next);}cout<<ans<<'\n';}}
